import { testnetFaucet } from '/app/components/testnet-beta-banner.js';
import { lock } from '/app/app/scroll-lock.js';

export async function mountWelcomeIntro(){
  await customElements.whenDefined('app-onboarding');
  const host=document.querySelector('app-onboarding');
  const dialog=host?.querySelector('.onb-dialog');
  if(!dialog||dialog.querySelector('.site-welcome-intro'))return;
  const intro=document.createElement('div');
  intro.className='site-welcome-intro';
  intro.innerHTML='<img class="onb-logo" src="/whitepaper/flame-logo.svg" alt=""><h2 id="site-welcome-title"><span>DEGENERUS</span><br>PROTOCOL</h2><p class="onb-copy" id="site-welcome-copy"></p>';
  const copy=intro.querySelector('.onb-copy'),faucet=testnetFaucet();
  if(faucet){
    copy.append('This is a testnet beta. ',document.createElement('br'));
    const link=document.createElement('a');link.href=faucet.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Click here to get testnet ETH.';copy.append(link);
  }else copy.textContent='Connect your wallet to play, or explore the demo.';
  dialog.prepend(intro);
  dialog.removeAttribute('aria-label');
  dialog.setAttribute('aria-labelledby','site-welcome-title');
  dialog.setAttribute('aria-describedby','site-welcome-copy');
  // A wallet reconnect must not dismiss an explicitly requested preview.
  if(new URLSearchParams(location.search).get('welcome')==='1'){
    const nativeShow=host.show;
    const open=()=>{
      if(!host.hidden)return;
      host.hidden=false;lock();
      if(!host.contains(document.activeElement))host.querySelector('[data-bind="onb-connect"]')?.focus();
    };
    // The native delayed first-visit callback can still fire; do not lock twice.
    host.show=open;
    const observer=new MutationObserver(()=>{if(host.hidden)open();});
    observer.observe(host,{attributes:true,attributeFilter:['hidden']});
    const onEscape=event=>{if(event.key==='Escape'&&!host.hidden){release();host.dismiss();}};
    const release=()=>{observer.disconnect();host.show=nativeShow;document.removeEventListener('keydown',onEscape,true);};
    host.addEventListener('click',event=>{
      if(event.target.closest('[data-bind="onb-connect"],[data-bind="onb-demo"],[data-bind="onb-dismiss"]'))release();
    },true);
    document.addEventListener('keydown',onEscape,true);
    open();
  }
}
